    "/api/chats": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        /**
         * Get inbox
         * @description Get inbox with all chats for authenticated user (customer or engineer). Shows list of conversations with last message preview, unread counts, and participant details.
         *
         *     ## Socket.IO
         *
         *     Connect to Socket.IO for real-time messaging:
         *
         *     **Server URL:** `https://resolvhome.onrender.com`
         *
         *     **Connection:**
         *     ```javascript
         *     const socket = io('https://resolvhome.onrender.com');
         *     ```
         *
         *     **Join a chat:**
         *     ```javascript
         *     socket.emit('join_chat', chatId);
         *     ```
         *
         *     **Send message:**
         *     ```javascript
         *     // Text message
         *     socket.emit('send_message', {
         *       chatId,
         *       message: 'Hello!',
         *       mediaType: 'text' // optional, defaults to 'text'
         *     });
         *
         *     // Image message
         *     socket.emit('send_message', {
         *       chatId,
         *       message: 'Check this out', // optional caption
         *       mediaType: 'image',
         *       mediaUrl: '/uploads/user123_image.jpg'
         *     });
         *
         *     // Video message
         *     socket.emit('send_message', {
         *       chatId,
         *       message: 'Video of the issue', // optional caption
         *       mediaType: 'video',
         *       mediaUrl: '/uploads/user123_video.mp4'
         *     });
         *     ```
         *
         *     **Receive messages:**
         *     ```javascript
         *     socket.on('receive_message', (message) => {
         *       // message: {
         *       //   id, chatId, senderId, message,
         *       //   mediaType: 'text' | 'image' | 'video',
         *       //   mediaUrl: string | null,
         *       //   isRead, createdAt
         *       // }
         *     });
         *     ```
         *
         *     **Typing indicator:**
         *     ```javascript
         *     // Emit when typing
         *     socket.emit('typing', { chatId });
         *
         *     // Listen for others typing
         *     socket.on('user_typing', ({ chatId, userId }) => {
         *       // Show "User is typing..."
         *     });
         *
         *     // Emit when stopped
         *     socket.emit('stop_typing', { chatId });
         *
         *     // Listen for others stopped
         *     socket.on('user_stopped_typing', ({ chatId, userId }) => {
         *       // Hide typing indicator
         *     });
         *     ```
         *
         *     **Online status:**
         *     ```javascript
         *     socket.on('user_online', ({ userId }) => {
         *       // User came online
         *     });
         *
         *     socket.on('user_offline', ({ userId }) => {
         *       // User went offline
         *     });
         *     ```
         */
        get: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: never;
            responses: {
                /** @description Inbox with list of chats */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            /** @example true */
                            success?: boolean;
                            data?: {
                                chats?: {
                                    /** @description Chat ID */
                                    id?: string;
                                    /** @description Associated booking ID */
                                    bookingId?: string;
                                    otherParticipant?: {
                                        id?: string;
                                        name?: string;
                                        image?: string;
                                        /** @enum {string} */
                                        role?: "customer" | "worker";
                                    };
                                    lastMessage?: {
                                        /** @description Message text or caption */
                                        message?: string;
                                        /**
                                         * @description Message type
                                         * @enum {string}
                                         */
                                        mediaType?: "text" | "image" | "video";
                                        /** @description URL to image/video file */
                                        mediaUrl?: string | null;
                                        senderId?: string;
                                        /** Format: date-time */
                                        createdAt?: string;
                                    } | null;
                                    /** @description Number of unread messages */
                                    unreadCount?: number;
                                    /** Format: date-time */
                                    createdAt?: string;
                                    /** Format: date-time */
                                    lastMessageAt?: string;
                                }[];
                            };
                        };
                    };
                };
                /** @description Unauthorized */
                401: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            /** @example false */
                            success?: boolean;
                            /** @example Unauthorized - Please sign in */
                            error?: string;
                        };
                    };
                };
            };
        };
        put?: never;
        post?: never;
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
